  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']

    # Validate required fields
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('Invalid payload structure')

    # Build node map and children map
    node_map = {}
    children_map = {}
    for node in nodes:
        nid = node.get('id')
        parent = node.get('parent')
        symbol = node.get('symbol')
        depth = node.get('depth')
        removable = node.get('removable')
        utility = node.get('utility')  # not used
        if nid is None or parent is None and nid != 'root':
            raise ValueError('Missing or invalid node id/parent')
        if nid in node_map:
            raise ValueError('Duplicate node id')
        node_map[nid] = node
        if parent is not None:
            children_map.setdefault(parent, []).append(nid)

    # Ensure root exists
    if 'root' not in node_map:
        raise ValueError('Missing root node')
    root_id = 'root'

    # Precompute subtree sets (including node itself)
    memo = {}
    def get_subtree(nid):
        if nid in memo:
            return memo[nid]
        sub = {nid}
        for child in children_map.get(nid, []):
            sub |= get_subtree(child)
        memo[nid] = sub
        return sub

    for nid in node_map:
        get_subtree(nid)

    # Initial retained set: all nodes
    retained = set(node_map.keys())
    removed = []

    # Candidate nodes: removable and not root
    candidates = [n for n in node_map.values() if n['removable'] and n['id'] != root_id]
    # Sort by depth descending, then by id ascending
    candidates.sort(key=lambda n: (-n['depth'], n['id']))

    # Helper to get symbols present in a set of node ids
    def symbols_in_set(nids):
        syms = set()
        for nid in nids:
            syms.add(node_map[nid]['symbol'])
        return syms

    for node in candidates:
        nid = node['id']
        if nid not in retained:
            continue
        subtree = memo[nid]
        # Check if removing node would also remove retained children
        retained_descendants = subtree & retained - {nid}
        if retained_descendants:
            continue
        # Check if all required symbols remain after removal
        new_retained = retained - subtree
        symbols_after = symbols_in_set(new_retained)
        if all(req in symbols_after for req in required_symbols):
            removed.append(nid)
            retained = new_retained

    retained_ids = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_ids
    }"
